import { createDocument, getCurrentDocument, setCurrentDocument, updateDocumentContent, updateDocumentTitle } from './document.js';
import { saveProject, exportProject, openProject, clearCurrentPath, listLibraryDocuments, loadLibraryDocument, deleteLibraryDocument } from './filesystem.js';
import { createFontPicker } from './font-picker.js';
import { portraitForRecord, newPortraitSeed } from './character-visuals.js';

const CATEGORY_KEY = 'scriptsmith-categories-v1';
const SETTINGS_KEY = 'scriptsmith-settings-v2';
const UNIVERSE_KEY = 'scriptsmith-universes-v1';

// Global universes: top-level worldbuilding, visible on the library home screen
// and linkable from any manuscript. Stored at app level, not per-manuscript.
function readUniverses(){try{const u=JSON.parse(localStorage.getItem(UNIVERSE_KEY)||'[]');return Array.isArray(u)?u:[];}catch{return [];}}
function writeUniverses(list){localStorage.setItem(UNIVERSE_KEY,JSON.stringify(list));}
function newUniverseId(){return 'u'+Date.now().toString(36)+Math.random().toString(36).slice(2,7);}
function addUniverse(name){const list=readUniverses();const u={id:newUniverseId(),name:String(name||'Untitled Universe').trim()||'Untitled Universe',description:'',summary:'',history:'',culture:'',geography:'',createdAt:now(),updatedAt:now()};list.push(u);writeUniverses(list);return u;}
function getUniverse(id){return readUniverses().find(u=>u.id===id)||null;}
function saveUniverse(u){const list=readUniverses();const i=list.findIndex(x=>x.id===u.id);u.updatedAt=now();if(i>=0)list[i]=u;else list.push(u);writeUniverses(list);}
function deleteUniverse(id){writeUniverses(readUniverses().filter(u=>u.id!==id));}
const BUILTIN_CATEGORIES = ['Novels','Novellas','Short Stories','Poetry','Screenplays','Essays','Other'];
const FONT_SIZES = Array.from({length: 73}, (_, i) => i + 8);
const ESC = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid = () => crypto.randomUUID();
const now = () => new Date().toISOString();
const countWords = text => String(text || '').trim() ? String(text).trim().split(/\s+/).length : 0;
const countCharacters = text => String(text || '').length;
const formatDate = value => { try { return new Intl.DateTimeFormat(undefined,{dateStyle:'medium'}).format(new Date(value)); } catch { return ''; } };
function readSettings(){try{return {autosave:true,autosaveInterval:10,spellcheck:true,showPageNumbers:true,...JSON.parse(localStorage.getItem(SETTINGS_KEY)||'{}')};}catch{return {autosave:true,autosaveInterval:10,spellcheck:true,showPageNumbers:true};}}
function writeSettings(settings){localStorage.setItem(SETTINGS_KEY,JSON.stringify(settings));}
function readCategories(){try{const custom=JSON.parse(localStorage.getItem(CATEGORY_KEY)||'[]');return [...BUILTIN_CATEGORIES,...(Array.isArray(custom)?custom:[])];}catch{return [...BUILTIN_CATEGORIES];}}
function addCategory(name){const clean=String(name||'').trim();if(!clean)return false;if(readCategories().some(x=>x.toLowerCase()===clean.toLowerCase()))return false;const custom=readCategories().filter(x=>!BUILTIN_CATEGORIES.includes(x));custom.push(clean);localStorage.setItem(CATEGORY_KEY,JSON.stringify(custom));return true;}
function removeCategory(name){if(BUILTIN_CATEGORIES.includes(name))return false;localStorage.setItem(CATEGORY_KEY,JSON.stringify(readCategories().filter(x=>!BUILTIN_CATEGORIES.includes(x)&&x!==name)));return true;}

export function initApp(){
  const root=document.querySelector('#app');setCurrentDocument(createDocument());clearCurrentPath();
  let currentView='library',currentRecord=null,activeChapterId=null,saveTimer=null,portalWorldFilter='all';
  const doc=()=>getCurrentDocument();
  const metadata=()=>{const d=doc();d.metadata=d.metadata||{};return d.metadata;};
  const chapters=()=>{const m=metadata();m.chapters=Array.isArray(m.chapters)?m.chapters:[];return m.chapters;};
  const records=key=>{const m=metadata();m[key]=Array.isArray(m[key])?m[key]:[];return m[key];};
  const oneLine=text=>{const s=String(text||'').split('\n')[0].trim();return s.length>110?s.slice(0,110)+'…':s;};
  function statusColor(status){const s=String(status||'').toLowerCase().trim();if(/^(alive|living|active)$/.test(s))return '#2e7d32';if(/^(dead|deceased|died)$/.test(s))return '#7a1f1f';if(/^draft/.test(s))return '#9e9e9e';if(/missing|unknown/.test(s))return '#ef6c00';if(!s)return '#bdbdbd';let h=0;for(const ch of s)h=(h*31+ch.charCodeAt(0))>>>0;return `hsl(${h%360},45%,45%)`;}
  const modalRoot=()=>document.querySelector('#ss-modal-root');const workspaceEl=()=>document.querySelector('#ss-workspace');const libraryEl=()=>document.querySelector('#ss-library');
  const toast=message=>{const n=document.createElement('div');n.className='ss-toast';n.textContent=message;document.body.appendChild(n);setTimeout(()=>n.remove(),2200);};
  root.innerHTML='<div id="ss-library" class="ss-app"></div><div id="ss-workspace" class="ss-app" hidden></div><div id="ss-modal-root"></div>';

  function showLibrary(){currentView='library';currentRecord=null;activeChapterId=null;workspaceEl().hidden=true;libraryEl().hidden=false;libraryEl().innerHTML=`<header class="ss-library-header"><div class="ss-brand"><span class="ss-mark">S</span><span><strong>ScriptSmith</strong><small>Writer's Studio</small></span></div><button class="ss-button" data-action="settings">Settings</button></header><main class="ss-library-main"><section class="ss-library-intro"><div><p class="ss-eyebrow">YOUR LIBRARY</p><h1>What will you write?</h1><p>Choose a category to open its dedicated library.</p></div><div class="ss-library-actions"><button class="ss-primary" data-action="new">+ New Manuscript</button><button class="ss-button" data-action="open">Open from computer</button></div></section><section class="ss-category-section"><div class="ss-section-head"><div><h2>Projects</h2><p>Each manuscript opens in its own workspace.</p></div><button class="ss-button" data-action="category-add">+ New Category</button></div><div id="ss-category-grid" class="ss-category-grid"></div></section><section class="ss-universe-section"><div class="ss-section-head"><div><h2>My Universes</h2><p>Your worlds, front and center — bigger than any single manuscript.</p></div><button class="ss-button" data-action="universe-add">+ New Universe</button></div><div id="ss-universe-grid" class="ss-category-grid"></div></section><section class="ss-project-section"><div class="ss-section-head"><div><h2 id="ss-project-heading">All Manuscripts</h2><p id="ss-project-subheading">Saved projects</p></div><button class="ss-button" data-action="refresh">Refresh</button></div><div id="ss-project-grid" class="ss-project-grid"></div></section></main>`;renderCategories();renderUniverses();renderProjects();libraryEl().onclick=async e=>{const a=e.target.closest('[data-action]');if(!a)return;const action=a.dataset.action;if(action==='new')newManuscript();if(action==='open'){const d=await openProject();if(d)openManuscript(d);}if(action==='refresh')renderProjects();if(action==='category-add'){if(addCategory(prompt('New category name:')))renderCategories();}if(action==='universe-add'){const u=addUniverse(prompt('New universe name:'));if(u)renderUniverses();}if(action==='settings')showSettings();};}
  function renderCategories(selected=null){const grid=document.querySelector('#ss-category-grid');if(!grid)return;grid.innerHTML=readCategories().map(c=>`<button class="ss-category-card ${selected===c?'selected':''}" data-category="${ESC(c)}"><strong>${ESC(c)}</strong><span>${BUILTIN_CATEGORIES.includes(c)?'Built-in category':'Custom category'}</span>${BUILTIN_CATEGORIES.includes(c)?'':`<i title="Delete category" data-delete-category="${ESC(c)}">×</i>`}</button>`).join('');grid.querySelectorAll('[data-category]').forEach(b=>b.onclick=e=>{if(e.target.closest('[data-delete-category]'))return;renderProjects(b.dataset.category);grid.querySelectorAll('.ss-category-card').forEach(x=>x.classList.toggle('selected',x===b));});grid.querySelectorAll('[data-delete-category]').forEach(x=>x.onclick=e=>{e.stopPropagation();const name=x.dataset.deleteCategory;if(confirm(`Delete category "${name}"? Manuscripts already saved in it will not be deleted.`)){removeCategory(name);renderCategories();renderProjects();}});}
  function renderUniverses(){const grid=document.querySelector('#ss-universe-grid');if(!grid)return;const list=readUniverses();grid.innerHTML=list.length?list.map(u=>`<button class="ss-category-card" data-universe="${ESC(u.id)}"><strong>${ESC(u.name||'Untitled Universe')}</strong><span>${ESC(u.summary?oneLine(u.summary):'Universe')}</span><i title="Delete universe" data-delete-universe="${ESC(u.id)}">×</i></button>`).join(''):'<div class="ss-empty"><strong>No universes yet.</strong><span>Create one to start building a world bigger than any single manuscript.</span></div>';grid.querySelectorAll('[data-universe]').forEach(b=>b.onclick=e=>{if(e.target.closest('[data-delete-universe]'))return;showUniverseDetail(b.dataset.universe);});grid.querySelectorAll('[data-delete-universe]').forEach(x=>x.onclick=e=>{e.stopPropagation();const id=x.dataset.deleteUniverse;const u=getUniverse(id);if(confirm(`Delete universe "${u&&u.name?u.name:'this universe'}"? This cannot be undone.`)){deleteUniverse(id);renderUniverses();}});}
  function showUniverseDetail(id){const u=getUniverse(id);if(!u)return;const grid=document.querySelector('#ss-universe-grid');if(!grid)return;const fields=[['summary','Summary'],['description','Description'],['history','History'],['culture','Culture'],['geography','Geography']];const body=fields.map(([k,l])=>u[k]?`<div class="ss-record-field"><h3>${l}</h3><p>${ESC(u[k])}</p></div>`:'').join('');grid.innerHTML=`<div class="ss-panel"><div class="ss-panel-head"><div><button class="ss-button" id="ss-universe-back">‹ Back</button><p class="ss-eyebrow">UNIVERSE</p><h1>${ESC(u.name||'Untitled Universe')}</h1></div></div>${body||'<p>No details yet.</p>'}</div>`;const back=document.querySelector('#ss-universe-back');if(back)back.onclick=()=>renderUniverses();}
  async function renderProjects(category=null){const grid=document.querySelector('#ss-project-grid');if(!grid)return;const heading=document.querySelector('#ss-project-heading'),sub=document.querySelector('#ss-project-subheading');if(heading)heading.textContent=category||'All Manuscripts';if(sub)sub.textContent=category?`Projects in ${category}`:'Saved projects';const docs=await listLibraryDocuments(),filtered=category?docs.filter(d=>(d.metadata?.libraryCategory||'Other')===category):docs;grid.innerHTML=filtered.length?filtered.map(d=>`<article class="ss-project-card"><button class="ss-project-open" data-id="${ESC(d.libraryId||d.id)}"><span class="ss-project-icon">S</span><span><strong>${ESC(d.title||'Untitled Manuscript')}</strong><small>${ESC(d.metadata?.libraryCategory||'Other')} · ${formatDate(d.libraryUpdatedAt||d.updatedAt)}</small></span></button><button class="ss-project-delete" title="Delete manuscript" data-delete-id="${ESC(d.libraryId||d.id)}">Delete</button></article>`).join(''):'<div class="ss-empty"><strong>No manuscripts here yet.</strong><span>Create a new manuscript or open one from your computer.</span></div>';grid.querySelectorAll('[data-id]').forEach(b=>b.onclick=async()=>{const found=filtered.find(d=>(d.libraryId||d.id)===b.dataset.id);if(found)openManuscript(await loadLibraryDocument(found));});grid.querySelectorAll('[data-delete-id]').forEach(b=>b.onclick=async()=>{if(confirm('Delete this manuscript from the ScriptSmith library?')){await deleteLibraryDocument(b.dataset.deleteId);renderProjects(category);}});}
  function newManuscript(type='document',category=null){const d=createDocument();d.type=type;d.title='Untitled Manuscript';d.metadata.libraryCategory=category;d.metadata.chapters=[];setCurrentDocument(d);currentRecord=null;activeChapterId=null;renderWorkspace();}
  function openManuscript(d){setCurrentDocument(d);currentRecord=null;activeChapterId=null;renderWorkspace();}
  function renderWorkspace(){libraryEl().hidden=true;workspaceEl().hidden=false;currentView='writing';const d=doc();workspaceEl().innerHTML=`<header class="ss-work-header"><div class="ss-work-brand"><button class="ss-back" data-action="back">‹ Library</button><span class="ss-mark">S</span><span><strong>ScriptSmith</strong><small>${ESC(d.metadata?.libraryCategory||'Manuscript')}</small></span></div><div class="ss-title-wrap"><input id="ss-title" value="${ESC(d.title)}" aria-label="Manuscript title"></div><div class="ss-work-actions"><span id="ss-save-status">Ready</span><button class="ss-button" data-action="new">New</button><button class="ss-button" data-action="open">Open</button><button class="ss-primary" data-action="save">Save</button><button class="ss-button" data-action="save-as">Save As</button></div></header><nav class="ss-manuscript-tabs" aria-label="Manuscript workspace"><button class="active" data-view="writing">Writing</button><button data-view="manuscript">Manuscript</button><button data-view="prologue">Prologue</button><button data-view="epilogue">Epilogue</button><button data-view="characters">Characters</button><button data-view="worlds">Worlds</button><button data-view="portal">World Portal</button><button data-view="timeline">Timeline</button><button data-view="notes">Notes</button></nav><main class="ss-workspace-body"><section id="ss-view" class="ss-view"></section></main>`;document.querySelector('#ss-title').oninput=e=>{updateDocumentTitle(e.target.value);markDirty();};workspaceEl().onclick=handleWorkspaceClick;workspaceEl().querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>switchView(b.dataset.view));switchView('writing');}
  async function handleWorkspaceClick(e){const a=e.target.closest('[data-action]');if(!a)return;const action=a.dataset.action;if(action==='back'){syncWriting();showLibrary();return;}if(action==='new'){if(confirm('Start a new manuscript? Unsaved changes will remain unsaved.'))newManuscript();return;}if(action==='open'){syncWriting();const d=await openProject();if(d)openManuscript(d);return;}if(action==='save'){syncWriting();await saveCurrent();return;}if(action==='save-as'){syncWriting();if(await exportProject(doc()))toast('Export complete.');return;}if(action==='delete-record'){deleteRecord(a.dataset.key,a.dataset.id);return;}if(action==='add-record'){addRecord(a.dataset.key);return;}if(action==='add-chapter'){addChapter();return;}if(action==='delete-chapter'){deleteChapter(a.dataset.id);return;}if(action==='move-chapter'){moveChapter(a.dataset.id,Number(a.dataset.direction));return;}if(action==='save-front'){saveFrontMatter(a.dataset.type);return;}if(action==='save-notes'){saveNotes();return;}if(action==='save-timeline'){saveTimeline();return;}}
  function switchView(view){syncWriting();currentView=view;workspaceEl().querySelectorAll('.ss-manuscript-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='writing'){currentRecord=null;renderWriting();}else{activeChapterId=null;if(view==='manuscript')renderManuscript();else if(view==='prologue'||view==='epilogue')renderFrontMatter(view);else if(view==='characters')renderManager('characters','Characters','Character');else if(view==='worlds')renderManager('locations','Worlds','World');else if(view==='portal')renderPortal();else if(view==='timeline')renderTimeline();else if(view==='notes')renderNotes();}}
  function renderWriting(){const prefs=metadata().manuscriptPreferences||{},view=document.querySelector('#ss-view');view.innerHTML=`<section class="ss-writing-shell"><div class="ss-ribbon" id="ss-ribbon"><div class="ss-ribbon-tabs"><button class="active" data-ribbon="home">Home</button><button data-ribbon="styles">Styles</button><button data-ribbon="insert">Insert</button><button data-ribbon="layout">Layout</button><button data-ribbon="references">References</button><button data-ribbon="review">Review</button><button data-ribbon="view">View</button></div><div id="ss-ribbon-content"></div></div><div class="ss-editor-scroll"><div id="ss-pages" class="ss-pages"></div></div><footer class="ss-status"><span id="ss-word-count">0 words · 0 characters</span><span id="ss-page-count">1 page</span><span>100%</span></footer></section>`;buildRibbon('home');buildPages();document.querySelectorAll('[data-ribbon]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-ribbon]').forEach(x=>x.classList.toggle('active',x===b));buildRibbon(b.dataset.ribbon);});applyEditorPreferences(prefs);}
  function buildRibbon(tab){const r=document.querySelector('#ss-ribbon-content');if(!r)return;const btn=(cmd,label,title=label)=>`<button class="ss-tool" data-cmd="${cmd}" title="${title}">${label}</button>`;if(tab==='home')r.innerHTML=`<div class="ss-ribbon-group"><b>Clipboard</b><div>${btn('cut','Cut')} ${btn('copy','Copy')} ${btn('paste','Paste')}</div></div><div class="ss-ribbon-group"><b>Font</b><div><span id="ss-font-slot"></span><select id="ss-size">${FONT_SIZES.map(s=>`<option value="${s}">${s}</option>`).join('')}</select>${btn('bold','B','Bold')} ${btn('italic','I','Italic')} ${btn('underline','U','Underline')} ${btn('strikeThrough','S','Strikethrough')}<input id="ss-text-color" type="color" value="#000000" title="Text color"><input id="ss-highlight-color" type="color" value="#fff2a8" title="Highlight color"></div></div><div class="ss-ribbon-group"><b>Paragraph</b><div>${btn('justifyLeft','Left')} ${btn('justifyCenter','Center')} ${btn('justifyRight','Right')} ${btn('insertUnorderedList','• List')} ${btn('insertOrderedList','1. List')} ${btn('outdent','← Indent')} ${btn('indent','Indent →')}<select id="ss-spacing"><option value="1">Single</option><option value="1.15">1.15</option><option value="1.5">1.5</option><option value="2">Double</option></select></div></div><div class="ss-ribbon-group"><b>Styles</b><div><select id="ss-style"><option value="p">Normal</option><option value="h1">Heading 1</option><option value="h2">Heading 2</option><option value="h3">Heading 3</option><option value="blockquote">Quote</option></select></div></div>`;if(tab==='styles')r.innerHTML=`<div class="ss-ribbon-group"><b>Styles</b><div><button class="ss-tool" data-cmd="formatBlock" data-value="p">Normal</button><button class="ss-tool" data-cmd="formatBlock" data-value="h1">Title</button><button class="ss-tool" data-cmd="formatBlock" data-value="h2">Heading 1</button><button class="ss-tool" data-cmd="formatBlock" data-value="h3">Heading 2</button><button class="ss-tool" data-cmd="formatBlock" data-value="blockquote">Quote</button></div></div>`;if(tab==='insert')r.innerHTML=`<div class="ss-ribbon-group"><b>Pages</b><div>${btn('pageBreak','Page Break')} ${btn('sectionBreak','Section Break')}</div></div><div class="ss-ribbon-group"><b>Header & Footer</b><div>${btn('headerFooter','Header / Footer')} ${btn('pageNumbers','Page Numbers')}</div></div><div class="ss-ribbon-group"><b>Tables</b><div>${btn('table','Insert Table')}</div></div><div class="ss-ribbon-group"><b>Text</b><div>${btn('find','Find')} ${btn('replace','Find / Replace')}</div></div>`;if(tab==='layout')r.innerHTML=`<div class="ss-ribbon-group"><b>Page Setup</b><div><label>Paper <select id="ss-paper"><option value="letter">Letter 8.5 × 11</option><option value="a4">A4</option></select></label><label>Orientation <select id="ss-orientation"><option value="portrait">Portrait</option><option value="landscape">Landscape</option></select></label><label>Columns <select id="ss-columns"><option value="1">One</option><option value="2">Two</option><option value="3">Three</option></select></label></div></div><div class="ss-ribbon-group"><b>Margins</b><div>${btn('margins','Set Margins')}</div></div>`;if(tab==='references')r.innerHTML=`<div class="ss-ribbon-group"><b>Manuscript</b><div>${btn('toc','Table of Contents')} ${btn('wordCount','Word Count')}</div></div>`;if(tab==='review')r.innerHTML=`<div class="ss-ribbon-group"><b>Proofing</b><div>${btn('spellcheck','Spell Check')} ${btn('find','Find')} ${btn('replace','Find / Replace')}</div></div>`;if(tab==='view')r.innerHTML=`<div class="ss-ribbon-group"><b>View</b><div>${btn('zoomOut','− Zoom')} ${btn('zoomIn','+ Zoom')} ${btn('zoomReset','100%')} ${btn('pageNumbers','Page Numbers')}</div></div>`;bindRibbon();}
  function applyFont(font){const ed=document.querySelector('#ss-pages .ss-page.active [contenteditable]')||document.querySelector('#ss-pages [contenteditable]');if(!ed)return;ed.focus();try{document.execCommand('fontName',false,font);}catch{}ed.dispatchEvent(new Event('input',{bubbles:true}));}
  function bindRibbon(){document.querySelectorAll('#ss-ribbon [data-cmd]').forEach(b=>b.onclick=()=>execTool(b.dataset.cmd,b.dataset.value||null));const fontSlot=document.querySelector('#ss-font-slot');if(fontSlot)fontSlot.replaceChildren(createFontPicker({current:'Georgia',onPick:applyFont}));const size=document.querySelector('#ss-size');if(size)size.onchange=()=>{execCommand('fontSize','7');const sel=getSelection();if(sel?.anchorNode){const span=sel.anchorNode.parentElement;span?.style?.setProperty('font-size',`${size.value}pt`);onEditorInput();}};const spacing=document.querySelector('#ss-spacing');if(spacing)spacing.onchange=()=>setLineSpacing(Number(spacing.value));const style=document.querySelector('#ss-style');if(style)style.onchange=()=>execCommand('formatBlock',style.value);const tc=document.querySelector('#ss-text-color');if(tc)tc.oninput=()=>execCommand('foreColor',tc.value);const hc=document.querySelector('#ss-highlight-color');if(hc)hc.oninput=()=>execCommand('hiliteColor',hc.value);const paper=document.querySelector('#ss-paper');if(paper)paper.onchange=()=>setPagePref('paper',paper.value);const orientation=document.querySelector('#ss-orientation');if(orientation)orientation.onchange=()=>setPagePref('orientation',orientation.value);const columns=document.querySelector('#ss-columns');if(columns)columns.onchange=()=>setPagePref('columns',Number(columns.value));}
  function editor(){return document.querySelector('#ss-pages');}function focusEditor(){const e=editor();if(!e)return null;const p=e.querySelector('.ss-page.active [contenteditable]')||e.querySelector('[contenteditable]');p?.focus();return p;}function execCommand(cmd,value=null){focusEditor();try{document.execCommand(cmd,false,value);onEditorInput();}catch{}}
  function execTool(cmd,value=null){if(['bold','italic','underline','strikeThrough','justifyLeft','justifyCenter','justifyRight','insertUnorderedList','insertOrderedList','outdent','indent','cut','copy','paste'].includes(cmd)){execCommand(cmd);return;}if(cmd==='formatBlock')return execCommand('formatBlock',value||'p');if(cmd==='pageBreak')return insertPageBreak();if(cmd==='sectionBreak')return insertSectionBreak();if(cmd==='headerFooter')return editHeaderFooter();if(cmd==='pageNumbers'){metadata().manuscriptPreferences=metadata().manuscriptPreferences||{};metadata().manuscriptPreferences.pageNumbers=metadata().manuscriptPreferences.pageNumbers===false;applyEditorPreferences(metadata().manuscriptPreferences);markDirty();return;}if(cmd==='table'){insertTable(Math.max(1,Number(prompt('Rows:','2'))||2),Math.max(1,Number(prompt('Columns:','2'))||2));return;}if(cmd==='find')return findText();if(cmd==='replace')return replaceText();if(cmd==='toc'){switchView('manuscript');return;}if(cmd==='wordCount'){toast(`${countWords(allEditorText())} words · ${countCharacters(allEditorText())} characters`);return;}if(cmd==='spellcheck'){const e=focusEditor();if(e)e.spellcheck=!e.spellcheck;return;}if(cmd==='margins')return setMargins();if(cmd==='zoomIn')return changeZoom(.1);if(cmd==='zoomOut')return changeZoom(-.1);if(cmd==='zoomReset')return changeZoom(1,true);}
  function setLineSpacing(n){const e=focusEditor();if(e){e.style.lineHeight=String(n);metadata().manuscriptPreferences=metadata().manuscriptPreferences||{};metadata().manuscriptPreferences.lineSpacing=n;markDirty();}}function setPagePref(key,value){metadata().manuscriptPreferences=metadata().manuscriptPreferences||{};metadata().manuscriptPreferences[key]=value;applyEditorPreferences(metadata().manuscriptPreferences);markDirty();}function setMargins(){const v=Number(prompt('Page margin in inches (0.5–2):','1'));if(v>=.5&&v<=2)setPagePref('margin',v);}function changeZoom(delta,reset=false){const p=editor();if(!p)return;let z=reset?1:Number(p.dataset.zoom||1)+delta;z=Math.max(.6,Math.min(1.6,z));p.dataset.zoom=z;p.style.setProperty('--ss-zoom',z);}

  // The document model is canonical. This only materializes it into page views.
  // Generated pagination boundaries are presentation state; explicit page breaks are preserved.
  function buildPages(){
    const pagesEl=editor();if(!pagesEl)return;
    const source=activeRecordContent()||'';
    pagesEl.innerHTML='';
    const chunks=source.split(/<div class="scriptsmith-page-break"[^>]*>.*?<\/div>/g);
    chunks.forEach((html,i)=>{
      const page=addPage(html,i);
      if(i>0)page.dataset.explicitBreak='1';
    });
    if(!pagesEl.children.length)addPage('',0);
    activatePage(0);
    pagesEl.querySelectorAll('[contenteditable]').forEach(e=>e.addEventListener('focus',()=>activatePage(Number(e.closest('.ss-page').dataset.page)||0)));
    updateEditorStats();
  }
  function addPage(html='',index=null){const pagesEl=editor();if(!pagesEl)return;const page=document.createElement('article');page.className='ss-page';page.dataset.page=index??pagesEl.children.length;page.innerHTML=`<div class="ss-paper-header"></div><div class="ss-page-content" contenteditable="true" spellcheck="${readSettings().spellcheck}">${html}</div><div class="ss-paper-footer"></div>`;pagesEl.appendChild(page);return page;}
  function activatePage(i){editor()?.querySelectorAll('.ss-page').forEach((p,n)=>p.classList.toggle('active',n===i));}
  function allEditorText(){return [...(editor()?.querySelectorAll('.ss-page-content')||[])].map(x=>x.innerText).join('\n');}
  function activeRecordContent(){if(currentRecord)return records(currentRecord.key).find(r=>r.id===currentRecord.id)?.content||'';if(activeChapterId)return chapters().find(c=>c.id===activeChapterId)?.content||'';return doc().content||'';}

  // Never turn automatically generated page boundaries into permanent document page breaks.
  // Only boundaries that originated from an explicit Page Break command are persisted.
  function syncWriting(){
    if(currentView!=='writing')return;
    const e=editor();if(!e)return;
    const html=[...e.querySelectorAll('.ss-page')].map((p,i)=>{
      const content=p.querySelector('.ss-page-content')?.innerHTML||'';
      return i>0&&p.dataset.explicitBreak==='1'
        ? '<div class="scriptsmith-page-break" contenteditable="false">Page Break</div>'+content
        : content;
    }).join('');
    if(currentRecord){const r=records(currentRecord.key).find(x=>x.id===currentRecord.id);if(r)r.content=html;}
    else if(activeChapterId){const c=chapters().find(x=>x.id===activeChapterId);if(c)c.content=html;}
    else updateDocumentContent(html);
  }
  function onEditorInput(){syncWriting();updateEditorStats();markDirty();}
  function updateEditorStats(){const words=countWords(allEditorText()),chars=countCharacters(allEditorText()),pages=editor()?.querySelectorAll('.ss-page').length||1;const w=document.querySelector('#ss-word-count'),p=document.querySelector('#ss-page-count');if(w)w.textContent=`${words} words · ${chars} characters`;if(p)p.textContent=`${pages} ${pages===1?'page':'pages'}`;}
  
  function applyEditorPreferences(p){const pages=editor();if(!pages)return;pages.style.setProperty('--ss-margin',`${p.margin||1}in`);pages.style.setProperty('--ss-columns',(p.columns||1)>1?p.columns:'auto');pages.classList.toggle('ss-landscape',p.orientation==='landscape');document.querySelectorAll('.ss-page-content').forEach(e=>{e.style.lineHeight=String(p.lineSpacing||1);e.spellcheck=p.spellcheck!==false;});document.querySelectorAll('.ss-paper-header').forEach(h=>h.textContent=p.header||'');document.querySelectorAll('.ss-paper-footer').forEach(f=>{const n=Number(f.closest('.ss-page').dataset.page)+1;f.textContent=p.footer||((p.pageNumbers!==false)?`Page ${n}`:'');});}
  function insertPageBreak(){const e=focusEditor();if(!e)return;const br=document.createElement('div');br.className='scriptsmith-page-break';br.contentEditable='false';br.textContent='Page Break — click to remove';br.onclick=()=>{br.remove();onEditorInput();};const s=getSelection(),r=s?.rangeCount?s.getRangeAt(0):null;if(r&&e.contains(r.commonAncestorContainer)){r.collapse(false);r.insertNode(br);}else e.appendChild(br);onEditorInput();}
  function insertSectionBreak(){const e=focusEditor();if(!e)return;const br=document.createElement('div');br.className='scriptsmith-section-break';br.contentEditable='false';br.textContent='Section Break';e.appendChild(br);onEditorInput();}
  function insertTable(rows,cols){const e=focusEditor();if(!e)return;const table=document.createElement('table');table.className='ss-editor-table';for(let r=0;r<rows;r++){const tr=table.insertRow();for(let c=0;c<cols;c++)tr.insertCell().innerHTML='&nbsp;';}e.appendChild(table);onEditorInput();}
  function findText(){const q=prompt('Find text:');if(!q)return;if(!window.find?.(q))toast('Text not found.');}
  function replaceText(){const q=prompt('Find:');if(!q)return;const r=prompt('Replace with:');if(r===null)return;editor()?.querySelectorAll('.ss-page-content').forEach(x=>x.innerHTML=x.innerHTML.split(q).join(ESC(r)));onEditorInput();}
  function editHeaderFooter(){const m=metadata();m.manuscriptPreferences=m.manuscriptPreferences||{};const h=prompt('Header text:',m.manuscriptPreferences.header||'');if(h===null)return;const f=prompt('Footer text:',m.manuscriptPreferences.footer||'');if(f===null)return;m.manuscriptPreferences.header=h;m.manuscriptPreferences.footer=f;applyEditorPreferences(m.manuscriptPreferences);markDirty();}

  function renderManuscript(){activeChapterId=null;const view=document.querySelector('#ss-view'),a=chapters(),m=metadata();view.innerHTML=`<section class="ss-panel"><div class="ss-panel-head"><div><p class="ss-eyebrow">MANUSCRIPT</p><h1>Manuscript</h1><p>Organization only. Writing stays in the Writing tab.</p></div><button class="ss-primary" data-action="add-chapter">+ Chapter</button></div><div class="ss-toc-card"><h2>Table of Contents</h2><div class="ss-toc-mode"><label><input type="radio" name="tocmode" value="automatic" ${(m.tableOfContents?.mode||'automatic')==='automatic'?'checked':''}> Automatic from chapters</label><label><input type="radio" name="tocmode" value="manual" ${(m.tableOfContents?.mode||'automatic')==='manual'?'checked':''}> Manual</label></div><div class="ss-toc-list">${a.map((c,i)=>`<div class="ss-toc-row"><span>${i+1}.</span><input value="${ESC(c.title)}" data-chapter-title="${ESC(c.id)}"><div><button class="ss-primary" data-open-chapter="${ESC(c.id)}">Write</button><button class="ss-button" data-action="move-chapter" data-id="${ESC(c.id)}" data-direction="-1">↑</button><button class="ss-button" data-action="move-chapter" data-id="${ESC(c.id)}" data-direction="1">↓</button><button class="ss-button danger" data-action="delete-chapter" data-id="${ESC(c.id)}">Delete</button></div></div>`).join('')||'<div class="ss-empty">No chapters yet.</div>'}</div><div class="ss-front-summary"><span>Prologue</span><strong>${m.prologue?.enabled?'Included':'Not written'}</strong><span>Epilogue</span><strong>${m.epilogue?.enabled?'Included':'Not written'}</strong></div></div></section>`;view.querySelectorAll('[data-open-chapter]').forEach(b=>b.onclick=()=>{activeChapterId=b.dataset.openChapter;currentRecord=null;switchView('writing');});view.querySelectorAll('[data-chapter-title]').forEach(i=>i.oninput=()=>{const c=a.find(x=>x.id===i.dataset.chapterTitle);if(c){c.title=i.value;markDirty();}});view.querySelectorAll('input[name="tocmode"]').forEach(x=>x.onchange=()=>{m.tableOfContents=m.tableOfContents||{};m.tableOfContents.mode=x.value;markDirty();});}
  function addChapter(){const a=chapters();a.push({id:uid(),title:`Chapter ${a.length+1}`,content:''});markDirty();renderManuscript();}
  function deleteChapter(id){const a=chapters();if(a.length<=1){toast('A manuscript must keep at least one chapter.');return;}if(confirm('Delete this chapter and its writing?')){const i=a.findIndex(x=>x.id===id);if(i>=0)a.splice(i,1);markDirty();renderManuscript();}}
  function moveChapter(id,d){const a=chapters(),i=a.findIndex(x=>x.id===id),j=i+d;if(i<0||j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];markDirty();renderManuscript();}
  function renderFrontMatter(type){const m=metadata();m[type]=m[type]||{enabled:false,title:type==='prologue'?'Prologue':'Epilogue',content:''};const x=m[type];document.querySelector('#ss-view').innerHTML=`<section class="ss-panel ss-frontmatter"><div class="ss-panel-head"><div><p class="ss-eyebrow">${type.toUpperCase()}</p><h1>${type==='prologue'?'Prologue':'Epilogue'}</h1><p>Dedicated editing area. This is not a chapter.</p></div></div><label>Title<input id="ss-fm-title" value="${ESC(x.title)}"></label><label>Content<textarea id="ss-fm-content" rows="22">${ESC(x.content||'')}</textarea></label><div class="ss-form-actions"><button class="ss-primary" data-action="save-front" data-type="${type}">Save ${type}</button></div><details><summary>Writing guidance</summary><p>${type==='prologue'?'Use a prologue to establish context, voice, history, or a hook before Chapter 1.':'Use an epilogue for aftermath, closure, or a glimpse of what comes next after the main story.'}</p></details></section>`;}
  function saveFrontMatter(type){const m=metadata();m[type]=m[type]||{};m[type].title=document.querySelector('#ss-fm-title').value;m[type].content=document.querySelector('#ss-fm-content').value;m[type].enabled=Boolean(m[type].content.trim());markDirty();toast(`${type==='prologue'?'Prologue':'Epilogue'} saved.`);}
  function renderManager(key,title,label){const list=records(key),view=document.querySelector('#ss-view');view.innerHTML=`<section class="ss-panel"><div class="ss-panel-head"><div><p class="ss-eyebrow">${title.toUpperCase()}</p><h1>${title}</h1><p>Manage information belonging to this manuscript.</p></div><button class="ss-primary" data-action="add-record" data-key="${key}">+ Add ${label}</button></div><div class="ss-record-list">${list.length?list.map(r=>{const cvAvatar=key==='characters'?`<span class="ss-record-avatar" aria-hidden="true">${portraitForRecord(r).svg}</span>`:'';return `<article class="ss-record-card"><button class="ss-record-open" data-record-id="${ESC(r.id)}">${cvAvatar}<span class="ss-record-text"><strong>${ESC(r.name||`Untitled ${label}`)}</strong><span>${ESC(r.summary||'Open profile')}</span></span></button><button class="ss-button danger" data-action="delete-record" data-key="${key}" data-id="${ESC(r.id)}">Delete</button></article>`;}).join(''):`<div class="ss-empty"><strong>No ${title.toLowerCase()} yet.</strong><span>Add one to begin building this manuscript.</span></div>`}</div></section>`;view.querySelectorAll('[data-record-id]').forEach(b=>b.onclick=()=>openRecord(key,b.dataset.recordId,label));}
  function addRecord(key){const label=key==='characters'?'Character':'World',r={id:uid(),name:`New ${label}`,summary:'',content:'',createdAt:now(),updatedAt:now()};records(key).push(r);currentRecord={key,id:r.id};markDirty();renderRecordEditor(key,r.id,label);}
  function deleteRecord(key,id){if(!confirm('Delete this item?'))return;const a=records(key),i=a.findIndex(x=>x.id===id);if(i>=0)a.splice(i,1);currentRecord=null;markDirty();renderManager(key,key==='characters'?'Characters':'Worlds',key==='characters'?'Character':'World');}
  function openRecord(key,id,label){currentRecord={key,id};const r=records(key).find(x=>x.id===id);if(r)renderRecordEditor(key,id,label);}
  function portraitEditorHtml(r){const p=portraitForRecord(r);return `<div class="ss-portrait-row" id="ss-portrait-row"><div class="ss-portrait" id="ss-portrait" title="Procedural portrait — drawn offline from your notes, no AI involved">${p.svg}</div><div class="ss-portrait-meta"><button class="ss-button" id="ss-portrait-regen" type="button">🎲 Regenerate portrait</button><p class="ss-portrait-note">${p.monogram?'Add Appearance or Fashion notes, then save, to grow a portrait from this monogram.':'Procedural portrait drawn offline from your Appearance &amp; Fashion notes.'}</p><p class="ss-portrait-seed">Portrait seed <span id="ss-portrait-seed-num">${p.seed}</span></p></div></div>`;}
  function renderRecordEditor(key,id,label){const r=records(key).find(x=>x.id===id);if(!r)return;const character=key==='characters';const fields=character?[['appearance','Appearance'],['personality','Personality / temperament'],['psychology','Psychology / defense mechanisms'],['fears','Fears'],['desires','Core desires / motivations'],['values','Values / beliefs'],['flaws','Flaws / weaknesses'],['strengths','Strengths'],['backstory','Full backstory'],['adventure','Adventure / experiences'],['family','Family / relatives'],['relationships','Relationships'],['favoriteMusic','Favorite music / songs / artists'],['favoriteBooks','Favorite books'],['favoriteShows','Favorite shows / films'],['fashion','Fashion / clothing style'],['hobbies','Hobbies / interests'],['secrets','Secrets'],['characterArc','Character arc / growth']]:[['description','Description'],['history','History'],['culture','Culture'],['geography','Geography'],['people','People'],['politics','Politics'],['religion','Religion'],['technology','Technology'],['importantPlaces','Important places'],['notes','Notes']];document.querySelector('#ss-view').innerHTML=`<section class="ss-panel"><div class="ss-panel-head"><div><button class="ss-button" id="ss-record-back">‹ Back</button><p class="ss-eyebrow">${label.toUpperCase()}</p><h1>${character?'Character Bible':label}</h1></div><button class="ss-button danger" data-action="delete-record" data-key="${key}" data-id="${ESC(id)}">Delete</button></div>${character?portraitEditorHtml(r):''}<label>Name<input id="ss-record-name" value="${ESC(r.name||'')}"></label><label>Summary<textarea id="ss-record-summary" rows="3">${ESC(r.summary||'')}</textarea></label>${character?`<div class="ss-record-meta-row"><label>Role / archetype<input id="ss-record-role" value="${ESC(r.role||'')}"></label><label>Status<input id="ss-record-status" value="${ESC(r.status||'')}"></label></div>`:''}<div class="ss-profile-grid">${fields.map(([k,l])=>`<label>${l}<textarea data-profile-field="${k}" rows="4">${ESC(r[k]||'')}</textarea></label>`).join('')}</div>${character?worldTagHtml(r):worldCharsHtml(id)}<div class="ss-form-actions"><button class="ss-primary" id="ss-record-save">Save ${label}</button></div></section>`;document.querySelector('#ss-record-back').onclick=()=>renderManager(key,character?'Characters':'Worlds',label);document.querySelectorAll('[data-open-char]').forEach(b=>b.onclick=()=>openRecord('characters',b.dataset.openChar,'Character'));function syncRecordFields(){r.name=document.querySelector('#ss-record-name').value;r.summary=document.querySelector('#ss-record-summary').value;document.querySelectorAll('[data-profile-field]').forEach(x=>r[x.dataset.profileField]=x.value);if(character){const role=document.querySelector('#ss-record-role');if(role)r.role=role.value;const st=document.querySelector('#ss-record-status');if(st)r.status=st.value;r.worlds=[...document.querySelectorAll('[data-world-link]:checked')].map(x=>x.dataset.worldLink);}r.updatedAt=now();}document.querySelector('#ss-record-save').onclick=()=>{syncRecordFields();markDirty();paintPortrait(r,syncRecordFields);toast(`${label} saved.`);};bindPortraitRegen(r,syncRecordFields);}
  function paintPortrait(r,sync){const row=document.querySelector('#ss-portrait-row');if(!row)return;row.outerHTML=portraitEditorHtml(r);bindPortraitRegen(r,sync);}
  function bindPortraitRegen(r,sync){const b=document.querySelector('#ss-portrait-regen');if(b)b.onclick=()=>{sync();r.portraitSeed=newPortraitSeed();markDirty();paintPortrait(r,sync);toast('New portrait generated.');};}

  // Universal World Portal helpers (restored): cross-link characters <-> worlds.
function worldTagHtml(r){const worlds=records('locations');const mine=Array.isArray(r.worlds)?r.worlds:[];return `<fieldset class="ss-world-links"><legend>Worlds</legend><p>Tag the worlds this character belongs to.</p>${worlds.length?`<div class="ss-checkbox-list">${worlds.map(w=>`<label class="ss-check"><input type="checkbox" data-world-link="${ESC(w.id)}" ${mine.includes(w.id)?'checked':''}><span>${ESC(w.name||'Untitled World')}</span></label>`).join('')}</div>`:'<p>No worlds yet — add one from the Worlds tab.</p>'}</fieldset>`;}
function worldCharsHtml(id){const mine=records('characters').filter(c=>Array.isArray(c.worlds)&&c.worlds.includes(id));return `<div class="ss-world-links"><h3>Characters in this world</h3>${mine.length?`<div class="ss-checkbox-list">${mine.map(c=>`<button class="ss-button" data-open-char="${ESC(c.id)}">${ESC(c.name||'Untitled Character')}</button>`).join('')}</div>`:'<p>None yet — tag characters from their profiles.</p>'}</div>`;}
function renderPortal(){const chars=records('characters'),worlds=records('locations'),events=records('timeline'),view=document.querySelector('#ss-view');
  const worldName=id=>worlds.find(w=>w.id===id)?.name||'Unknown world';
  const charsInWorld=wid=>chars.filter(c=>Array.isArray(c.worlds)&&c.worlds.includes(wid));
  const filtered=portalWorldFilter==='all'?chars:portalWorldFilter==='none'?chars.filter(c=>!Array.isArray(c.worlds)||!c.worlds.length):charsInWorld(portalWorldFilter);
  const evText=e=>`${e.title||''} ${e.description||''}`;
  const eventMentions=e=>{const t=evText(e).toLowerCase();const hits=[];chars.forEach(c=>{if(c.name&&t.includes(c.name.toLowerCase()))hits.push(c.name);});worlds.forEach(w=>{if(w.name&&t.includes(w.name.toLowerCase()))hits.push(w.name);});return hits;};
  view.innerHTML=`<section class="ss-panel"><div class="ss-panel-head"><div><p class="ss-eyebrow">WORLD PORTAL</p><h1>World Portal</h1><p class="ss-portal-count">${chars.length} character${chars.length===1?'':'s'} · ${worlds.length} world${worlds.length===1?'':'s'} · ${events.length} timeline event${events.length===1?'':'s'}</p></div></div><div class="ss-portal-section"><h2>Characters</h2><div class="ss-filter-pills"><button class="ss-chip ${portalWorldFilter==='all'?'active':''}" data-portal-filter="all">All</button>${worlds.map(w=>`<button class="ss-chip ${portalWorldFilter===w.id?'active':''}" data-portal-filter="${ESC(w.id)}">${ESC(w.name||'Untitled World')}</button>`).join('')}<button class="ss-chip ${portalWorldFilter==='none'?'active':''}" data-portal-filter="none">No world</button></div><div class="ss-portal-grid">${filtered.length?filtered.map(c=>{const cw=(Array.isArray(c.worlds)?c.worlds:[]).map(worldName);return `<article class="ss-portal-card"><button class="ss-portal-open" data-portal-char="${ESC(c.id)}"><strong><span class="ss-status-dot" style="background:${statusColor(c.status)}" title="${ESC(c.status||'No status set')}"></span>${ESC(c.name||'Untitled Character')}</strong><span class="ss-portal-summary">${ESC(oneLine(c.summary)||'Open profile')}</span></button><div class="ss-portal-meta">${c.role?`<span class="ss-role">${ESC(c.role)}</span>`:''}${cw.map(n=>`<span class="ss-world-tag">${ESC(n)}</span>`).join('')}</div></article>`;}).join(''):'<div class="ss-empty"><strong>No characters here.</strong><span>Tag characters with a world from their profile.</span></div>'}</div></div><div class="ss-portal-section"><h2>Worlds</h2><div class="ss-portal-grid">${worlds.length?worlds.map(w=>{const mine=charsInWorld(w.id);const evs=w.name?events.filter(e=>evText(e).toLowerCase().includes(w.name.toLowerCase())):[];return `<article class="ss-portal-card"><button class="ss-portal-open" data-portal-world="${ESC(w.id)}"><strong>${ESC(w.name||'Untitled World')}</strong><span class="ss-portal-summary">${ESC(oneLine(w.summary)||'Open world')}</span></button><div class="ss-portal-meta"><span class="ss-count-pill">${mine.length} character${mine.length===1?'':'s'}</span><span class="ss-count-pill">${evs.length} timeline event${evs.length===1?'':'s'}</span></div>${mine.length?`<div class="ss-portal-names">${mine.map(c=>`<button class="ss-world-tag" data-portal-char="${ESC(c.id)}">${ESC(c.name||'Untitled Character')}</button>`).join('')}</div>`:''}</article>`;}).join(''):'<div class="ss-empty"><strong>No worlds yet.</strong><span>Add one from the Worlds tab.</span></div>'}</div></div><div class="ss-portal-section"><h2>Timeline</h2><div class="ss-timeline-mini">${events.length?events.map(e=>{const hits=eventMentions(e);return `<div class="ss-timeline-mini-row"><div><strong>${ESC(e.title||'Event')}</strong>${e.date?` <span class="ss-portal-count">${ESC(e.date)}</span>`:''}<p class="ss-portal-summary">${ESC(oneLine(e.description)||'')}</p></div>${hits.length?`<div class="ss-portal-meta">${hits.slice(0,4).map(h=>`<span class="ss-world-tag">${ESC(h)}</span>`).join('')}</div>`:''}</div>`;}).join(''):'<div class="ss-empty"><strong>No timeline events yet.</strong><span>Add events from the Timeline tab.</span></div>'}</div></div></section>`;
  view.querySelectorAll('[data-portal-filter]').forEach(b=>b.onclick=()=>{portalWorldFilter=b.dataset.portalFilter;renderPortal();});
  view.querySelectorAll('[data-portal-char]').forEach(b=>b.onclick=()=>openRecord('characters',b.dataset.portalChar,'Character'));
  view.querySelectorAll('[data-portal-world]').forEach(b=>b.onclick=()=>openRecord('locations',b.dataset.portalWorld,'World'));}
  function renderTimeline(){const list=records('timeline'),view=document.querySelector('#ss-view');view.innerHTML=`<section class="ss-panel"><div class="ss-panel-head"><div><p class="ss-eyebrow">TIMELINE</p><h1>Timeline</h1><p>Build and reorder the manuscript timeline.</p></div><button class="ss-primary" id="ss-add-timeline">+ Add Event</button></div><div id="ss-timeline-list">${list.length?list.map((e,i)=>`<article class="ss-timeline-row"><span class="ss-drag">☷</span><input data-timeline="title" data-index="${i}" value="${ESC(e.title||'Event')}"><input data-timeline="date" data-index="${i}" value="${ESC(e.date||'')}" placeholder="Date / time"><textarea data-timeline="description" data-index="${i}" rows="2" placeholder="Description">${ESC(e.description||'')}</textarea><button class="ss-button danger" data-timeline-delete="${i}">Delete</button></article>`).join(''):'<div class="ss-empty">No timeline events yet.</div>'}</div><div class="ss-form-actions"><button class="ss-primary" data-action="save-timeline">Save Timeline</button></div></section>`;document.querySelector('#ss-add-timeline').onclick=()=>{list.push({id:uid(),title:'New Event',date:'',description:''});markDirty();renderTimeline();};view.querySelectorAll('[data-timeline]').forEach(x=>x.oninput=()=>{list[Number(x.dataset.index)][x.dataset.timeline]=x.value;markDirty();});view.querySelectorAll('[data-timeline-delete]').forEach(x=>x.onclick=()=>{if(confirm('Delete this timeline event?')){list.splice(Number(x.dataset.timelineDelete),1);markDirty();renderTimeline();}});}
  function saveTimeline(){markDirty();toast('Timeline saved.');}
  function renderNotes(){const m=metadata();m.notes=Array.isArray(m.notes)?m.notes:[];const view=document.querySelector('#ss-view');view.innerHTML=`<section class="ss-panel"><div class="ss-panel-head"><div><p class="ss-eyebrow">NOTES</p><h1>Notes</h1><p>Keep notes organized inside this manuscript.</p></div><button class="ss-primary" id="ss-add-note">+ New Note</button></div><div id="ss-notes-list">${m.notes.length?m.notes.map((n,i)=>`<article class="ss-note-box"><div class="ss-note-head"><input data-note="name" data-index="${i}" value="${ESC(n.name||'Note')}"><button class="ss-button danger" data-note-delete="${i}">Delete</button></div><textarea data-note="content" data-index="${i}" rows="8">${ESC(n.content||'')}</textarea></article>`).join(''):'<div class="ss-empty">No notes yet.</div>'}</div><div class="ss-form-actions"><button class="ss-primary" data-action="save-notes">Save Notes</button></div></section>`;document.querySelector('#ss-add-note').onclick=()=>{m.notes.push({id:uid(),name:'New Note',content:''});markDirty();renderNotes();};view.querySelectorAll('[data-note]').forEach(x=>x.oninput=()=>{m.notes[Number(x.dataset.index)][x.dataset.note]=x.value;markDirty();});view.querySelectorAll('[data-note-delete]').forEach(x=>x.onclick=()=>{if(confirm('Delete this note?')){m.notes.splice(Number(x.dataset.noteDelete),1);markDirty();renderNotes();}});}
  function saveNotes(){markDirty();toast('Notes saved.');}
  async function saveCurrent(){const d=doc();d.metadata=d.metadata||{};if(!d.metadata.libraryCategory){showSaveCategory();return false;}d.updatedAt=now();try{await saveProject(d);markClean();toast('Manuscript saved.');return true;}catch(err){toast('Save failed.');console.error(err);return false;}}
  function showSaveCategory(){const opts=readCategories().map(c=>`<option value="${ESC(c)}">${ESC(c)}</option>`).join('');modalRoot().innerHTML=`<div class="ss-modal-backdrop"><div class="ss-modal"><h2>Where would you like to save this manuscript?</h2><p>Choose its library category. ScriptSmith will remember this choice for future saves.</p><select id="ss-save-category">${opts}</select><div class="ss-modal-actions"><button class="ss-button" id="ss-save-cancel">Cancel</button><button class="ss-primary" id="ss-save-confirm">Save Manuscript</button></div></div></div>`;document.querySelector('#ss-save-cancel').onclick=()=>modalRoot().innerHTML='';document.querySelector('#ss-save-confirm').onclick=async()=>{doc().metadata.libraryCategory=document.querySelector('#ss-save-category').value;modalRoot().innerHTML='';await saveCurrent();};}
  function showSettings(){const s=readSettings();modalRoot().innerHTML=`<div class="ss-modal-backdrop"><div class="ss-modal ss-settings"><h2>Settings</h2><div class="ss-settings-grid"><label><span>Automatic recovery/autosave</span><input id="ss-set-autosave" type="checkbox" ${s.autosave?'checked':''}></label><label><span>Autosave interval (seconds)</span><select id="ss-set-interval"><option>5</option><option>10</option><option>30</option><option>60</option></select></label><label><span>Spellcheck by default</span><input id="ss-set-spellcheck" type="checkbox" ${s.spellcheck?'checked':''}></label><label><span>Show page numbers by default</span><input id="ss-set-pages" type="checkbox" ${s.showPageNumbers?'checked':''}></label></div><div class="ss-modal-actions"><button class="ss-button" id="ss-settings-cancel">Cancel</button><button class="ss-primary" id="ss-settings-save">Save Settings</button></div></div></div>`;document.querySelector('#ss-set-interval').value=String(s.autosaveInterval);document.querySelector('#ss-settings-cancel').onclick=()=>modalRoot().innerHTML='';document.querySelector('#ss-settings-save').onclick=()=>{s.autosave=document.querySelector('#ss-set-autosave').checked;s.autosaveInterval=Number(document.querySelector('#ss-set-interval').value);s.spellcheck=document.querySelector('#ss-set-spellcheck').checked;s.showPageNumbers=document.querySelector('#ss-set-pages').checked;writeSettings(s);modalRoot().innerHTML='';applyEditorPreferences(metadata().manuscriptPreferences||{});toast('Settings saved.');};}
  function markDirty(){const s=document.querySelector('#ss-save-status');if(s)s.textContent='Unsaved changes';if(saveTimer)clearTimeout(saveTimer);const settings=readSettings();if(settings.autosave){saveTimer=setTimeout(async()=>{syncWriting();try{await saveProject(doc());if(s)s.textContent='Autosaved';}catch{}},settings.autosaveInterval*1000);}}
  function markClean(){const s=document.querySelector('#ss-save-status');if(s)s.textContent='Saved';}
  showLibrary();
}